class Account {
  public:
    void transfer_to(Account& to, long amount) {
        std::scoped_lock guard(m_, to.m_);   // deadlock-avoiding multi-lock
        balance_ -= amount; to.balance_ += amount;
    }
    long balance() const { std::lock_guard<std::mutex> g(m_); return balance_; }
  private:
    mutable std::mutex m_;
    long balance_ = 0;
};

