class Gate {                        // models BasicLockable/Lockable
  public:
    void lock()    { m_.lock(); }
    void unlock()  { m_.unlock(); }
    bool try_lock(){ return m_.try_lock(); }
  private:
    std::mutex m_;
};

void use(Shared& s, Gate& gate) {
    std::lock_guard<Gate> guard(gate);   // generic wrappers accept it
    s.mutate();
}
